Write-Host 'PATCH-008 - Teammate Feature Merge' -ForegroundColor Cyan
Write-Host 'Checking the local project against the uploaded PATCH-007 baseline...' -ForegroundColor DarkCyan
$needsWrite = New-Object 'System.Collections.Generic.List[string]'
foreach ($relative in $files.Keys) {
    $target = Join-Path $root $relative
    $current = Sha256 $target
    $expectedBase = $files[$relative].Base
    $expectedNew = $files[$relative].New
    if ($current -eq $expectedNew) { continue }
    if ($expectedBase -eq '') {
        if ($current -ne '') { throw "PATCH-008 stopped: new target already exists with different content: $relative" }
    } elseif ($current -ne $expectedBase) {
        throw "PATCH-008 stopped: $relative changed after the uploaded baseline. No files were overwritten."
    }
    $needsWrite.Add($relative)
}

$sourceChanged = $needsWrite.Count -gt 0
if ($sourceChanged) {
    New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
    foreach ($relative in $needsWrite) {
        $target = Join-Path $root $relative
        if (Test-Path -LiteralPath $target -PathType Leaf) {
            $backup = Join-Path $backupRoot $relative
            $backupParent = Split-Path -Parent $backup
            if (-not (Test-Path -LiteralPath $backupParent)) { New-Item -ItemType Directory -Force -Path $backupParent | Out-Null }
            Copy-Item -LiteralPath $target -Destination $backup -Force
        }
    }

