    Write-Host 'PATCH-008 source files are already installed; validation and database checks will still run.' -ForegroundColor Green
}

$php = 'D:\xampp\php\php.exe'
if (-not (Test-Path -LiteralPath $php)) {
    $phpCmd = Get-Command php -ErrorAction SilentlyContinue
    if (-not $phpCmd) {
        if ($sourceChanged) { Restore-PatchFiles $needsWrite $files }
        throw 'PHP CLI was not found. Install/start XAMPP or add PHP to PATH.'
    }
    $php = $phpCmd.Source
}

try {
    Write-Host 'Running full PHP lint...' -ForegroundColor DarkCyan
    $phpFiles = Get-ChildItem -LiteralPath $root -Recurse -Filter *.php -File | Where-Object { $_.FullName -notlike '*\patch-backups\*' }
    foreach ($file in $phpFiles) {
        & $php -l $file.FullName | Out-Null
        if ($LASTEXITCODE -ne 0) { throw "PHP lint failed: $($file.FullName)" }
    }
    Write-Host ("PHP lint OK: {0} files" -f $phpFiles.Count) -ForegroundColor Green

    Write-Host 'Running regression and feature tests...' -ForegroundColor DarkCyan
    & $php (Join-Path $root 'tests\run.php')
    if ($LASTEXITCODE -ne 0) { throw 'Automated tests failed.' }
} catch {
    if ($sourceChanged) {
        Write-Host 'Validation failed. Restoring the source backup...' -ForegroundColor Red
        Restore-PatchFiles $needsWrite $files
    }
    throw
}

Write-Host 'Applying the idempotent gamification migration...' -ForegroundColor DarkCyan
& $php (Join-Path $root 'database\migrate_008_gamification.php')
$migrationOk = $LASTEXITCODE -eq 0
if (-not $migrationOk) {
    Write-Warning 'Source PATCH-008 passed validation, but the database migration did not run. Start MySQL and run: D:\xampp\php\php.exe database\migrate_008_gamification.php'
} else {
    Write-Host 'Running database optimizer...' -ForegroundColor DarkCyan
    & $php (Join-Path $root 'database\optimize_cli.php')
    if ($LASTEXITCODE -ne 0) { Write-Warning 'Feature migration succeeded, but database ANALYZE/index optimization reported an error.' }
}

Write-Host ''
if ($migrationOk) {
    Write-Host 'PATCH-008 APPLIED SUCCESSFULLY' -ForegroundColor Green
    Write-Host 'Existing landing/auth/UI files outside the merge were left untouched.' -ForegroundColor Yellow
    Write-Host 'Open http://localhost/codeforge/ and continue through dashboard.php after login.' -ForegroundColor White
    exit 0
}

Write-Host 'PATCH-008 SOURCE APPLIED; DATABASE MIGRATION PENDING' -ForegroundColor Yellow
Write-Host 'The original app remains usable; gamification activates after the migration succeeds.' -ForegroundColor Yellow
exit 2
